import{_ as n,C as o,o as s,c as d,a2 as t,b as l,w as a,a as r,E as h,a3 as p}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse('{"title":"Installation","description":"Install the Pterodactyl Bandwidth Monitor — Blueprint panel addon setup (or standalone alternative), per-node Go agent pairing, verification, troubleshooting, uninstall and upgrades.","frontmatter":{"title":"Installation","description":"Install the Pterodactyl Bandwidth Monitor — Blueprint panel addon setup (or standalone alternative), per-node Go agent pairing, verification, troubleshooting, uninstall and upgrades."},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/getting-started/installation.md","filePath":"pterodactyl-bandwidth-monitor/getting-started/installation.md","lastUpdated":1787470737000}'),c={name:"pterodactyl-bandwidth-monitor/getting-started/installation.md"};function k(g,e,u,b,y,F){const i=o("Mermaid");return s(),d("div",null,[e[1]||(e[1]=t('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Bandwidth Monitor has two components, installed in this order:</p><ol><li><strong>Panel addon</strong> (<code>pterodactylbandwidth</code>) — a Blueprint extension on your Pterodactyl panel. Admin pages, per-node pairing tokens, per-server limits, usage rollups, reports and settings.</li><li><strong>Node agent</strong> (<code>bandwidth-noded</code>) — a Go daemon on every Wings node. Discovers server containers, counts rx/tx bytes, enforces limits with <code>tc</code>, and syncs with the panel.</li></ol>',3)),(s(),l(p,null,{default:a(()=>[h(i,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20ADDON%5B%22Bandwidth%20Monitor%20addon%3Cbr%2F%3E(Blueprint%3A%20pterodactylbandwidth)%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22bandwidth_*%20tables%22)%5D%0A%20%20%20%20%20%20%20%20ADDON%20--%3E%20DB%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node%5B%22Wings%20Node%22%5D%0A%20%20%20%20%20%20%20%20AGENT%5B%22bandwidth-noded%3Cbr%2F%3E%3A8480%22%5D%0A%20%20%20%20%20%20%20%20TC%5B%22tc%20(HTB%20%2B%20ingress%20police)%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Server%20container%20A%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Server%20container%20B%22%5D%0A%20%20%20%20%20%20%20%20AGENT%20--%3E%20TC%0A%20%20%20%20%20%20%20%20TC%20--%3E%20C1%0A%20%20%20%20%20%20%20%20TC%20--%3E%20C2%0A%20%20%20%20end%0A%0A%20%20%20%20AGENT%20--%3E%7C%22register%20%2F%20heartbeat%20%2F%20events%3Cbr%2F%3E(bearer%20token)%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22stats%20pulls%20%2F%20limits%20push%3Cbr%2F%3E(bearer%20token)%22%7C%20AGENT%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<div class="info custom-block"><p class="custom-block-title">VERIFIED ON A LIVE PANEL</p><p>The full flow described here — pairing, stats reporting, a 10 Mbps speed cap holding at ~9.5 Mbps, a 1 GiB quota triggering a 5 Mbps throttle with panel events, a weekly quota suspending a real server, and admin unthrottle — was tested end-to-end on a production panel and Wings node.</p></div><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="panel-server" tabindex="-1">Panel server <a class="header-anchor" href="#panel-server" aria-label="Permalink to &quot;Panel server&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Pterodactyl Panel</strong></td><td>v1.12.x or higher</td></tr><tr><td><strong>PHP</strong></td><td>8.2+ (the installer checks and refuses older versions)</td></tr><tr><td><strong>Blueprint</strong></td><td><code>beta-2026-05</code> or newer — only for the Blueprint install path</td></tr><tr><td><strong>Python 3</strong></td><td>Only for the standalone path (the blade patchers are Python)</td></tr><tr><td><strong>Root access</strong></td><td>The installer writes into the panel tree and runs migrations</td></tr></tbody></table><h3 id="each-wings-node" tabindex="-1">Each Wings node <a class="header-anchor" href="#each-wings-node" aria-label="Permalink to &quot;Each Wings node&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Linux with systemd</strong></td><td>The agent runs as a systemd service, as root (<code>tc</code> needs <code>CAP_NET_ADMIN</code>)</td></tr><tr><td><strong>Docker</strong></td><td>Wings already requires it; the agent discovers server containers through it</td></tr><tr><td><strong><code>tc</code> (iproute2)</strong></td><td>Required — the installer aborts if <code>tc</code> is not found</td></tr><tr><td><strong>Go 1.23+</strong></td><td>Only if building from source. If Go is present the installer builds automatically; otherwise it uses the prebuilt <code>./bandwidth-noded</code> shipped next to <code>install.sh</code></td></tr><tr><td><strong>Network</strong></td><td>The node must reach the panel over HTTP(S), and the panel must reach the node&#39;s API port (default <code>8480</code>)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">USE HTTPS FOR THE PANEL URL</p><p>The 64-hex bearer token and all bandwidth data cross the wire on every heartbeat. The installer warns if you enter a plain <code>http://</code> panel URL — use <code>https://</code> in production.</p></div><hr><h2 id="part-1-—-install-the-panel-addon" tabindex="-1">Part 1 — Install the panel addon <a class="header-anchor" href="#part-1-—-install-the-panel-addon" aria-label="Permalink to &quot;Part 1 — Install the panel addon&quot;">​</a></h2><h3 id="option-a-blueprint-recommended" tabindex="-1">Option A: Blueprint (recommended) <a class="header-anchor" href="#option-a-blueprint-recommended" aria-label="Permalink to &quot;Option A: Blueprint (recommended)&quot;">​</a></h3><p>Copy the <code>.blueprint</code> archive into your panel directory and install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # adjust if your panel lives elsewhere</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># place pterodactylbandwidth-v1.0.0.blueprint in this directory, then:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylbandwidth-v1.0.0</span></span></code></pre></div><p>The installer is idempotent — re-running it on the same panel will not corrupt anything. It:</p><ol><li><strong>Merges <code>PanelFiles/</code></strong> into the panel tree (controllers, services, jobs, migrations, routes, views) and records every installed file so the uninstaller removes exactly what was shipped.</li><li><strong>Registers the service provider</strong> — inserts <code>Pterodactyl\\Providers\\BandwidthMonitorServiceProvider::class</code> into <code>config/app.php</code>, with a timestamped backup and a <code>php -l</code> syntax check that rolls back on failure.</li><li><strong>Patches the views</strong> — injects the <strong>Bandwidth</strong> entry into the admin sidebar and the bandwidth fields into the server build configuration (<code>new.blade.php</code> / <code>build.blade.php</code>). All patches are marker-delimited and fully reversible.</li><li><strong>Runs the migrations</strong> — <code>php artisan migrate --force</code>, creating the 7 <code>bandwidth_*</code> tables (<code>bandwidth_node_tokens</code>, <code>bandwidth_server_limits</code>, <code>bandwidth_settings</code>, <code>bandwidth_usage_hourly</code>, <code>bandwidth_usage_daily</code>, <code>bandwidth_events</code>, <code>bandwidth_server_state</code>) plus an idempotent settings seed — 8 migrations in total.</li><li><strong>Clears the panel caches</strong> — <code>config:clear</code>, <code>route:clear</code>, <code>view:clear</code>, <code>cache:clear</code>, plus a best-effort <code>composer dump-autoload</code>.</li></ol><p>Existing node tokens are preserved on reinstall — no re-pairing is required.</p><h3 id="option-b-standalone-no-blueprint" tabindex="-1">Option B: Standalone (no Blueprint) <a class="header-anchor" href="#option-b-standalone-no-blueprint" aria-label="Permalink to &quot;Option B: Standalone (no Blueprint)&quot;">​</a></h3><p>The same installer ships as plain scripts under <code>standalone/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PANEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/www/pterodactyl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # adjust if your panel lives elsewhere</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PanelFiles/.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>This performs the same steps as the Blueprint path: provider registration, sidebar and build-view patching, migrations, cache clears. Python 3 must be installed for the view patchers.</p><div class="danger custom-block"><p class="custom-block-title">BACK UP FIRST</p><p>Both paths modify <code>config/app.php</code> and patch core blade views. Back up your panel files and database before installing. The installer creates its own backup of <code>config/app.php</code>, but that is no substitute for a real snapshot.</p></div><h3 id="post-install-verification" tabindex="-1">Post-install verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-install verification&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># All 8 bandwidth migrations should show &quot;Ran&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bandwidth</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Admin routes and the node API routes should be registered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bandwidth</span></span></code></pre></div><p>Then open <strong>Admin → Bandwidth</strong> (<code>/admin/bandwidth</code>) — the dashboard should load without errors.</p><div class="tip custom-block"><p class="custom-block-title">STALE ROUTES OR 500s AFTER INSTALL? RELOAD PHP-FPM</p><p>The installer clears Laravel&#39;s caches, but PHP opcache lives in the php-fpm process and can keep serving the old classmap. If <code>/admin/bandwidth</code> 404s or throws after a successful install, reload php-fpm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php8.2-fpm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # adjust for your PHP version</span></span></code></pre></div></div><hr><h2 id="part-2-—-install-the-node-agent-per-wings-node" tabindex="-1">Part 2 — Install the node agent (per Wings node) <a class="header-anchor" href="#part-2-—-install-the-node-agent-per-wings-node" aria-label="Permalink to &quot;Part 2 — Install the node agent (per Wings node)&quot;">​</a></h2><p>Repeat this on <strong>every</strong> Wings node you want monitored.</p><h3 id="_1-get-the-node-s-pairing-token" tabindex="-1">1. Get the node&#39;s pairing token <a class="header-anchor" href="#_1-get-the-node-s-pairing-token" aria-label="Permalink to &quot;1. Get the node&#39;s pairing token&quot;">​</a></h3><p>In the panel, open <strong>Admin → Bandwidth → Nodes</strong>. Every Pterodactyl node gets a row with a generated 64-character hex token. Click <strong>View Token</strong> to reveal it.</p><p>The token can be <strong>reset</strong> from the same page at any time — a new token is generated and the old one dies immediately. The panel stores only a bcrypt hash plus an encrypted copy (so you can re-view it); the plaintext token is never stored.</p><h3 id="_2-run-the-installer" tabindex="-1">2. Run the installer <a class="header-anchor" href="#_2-run-the-installer" aria-label="Permalink to &quot;2. Run the installer&quot;">​</a></h3><p>Copy the <code>node-module/</code> directory to the Wings node, then as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>The installer prompts (via <code>/dev/tty</code>, so it also works through <code>curl | bash</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Panel URL (e.g. https://panel.example.com): https://panel.example.com</span></span>
<span class="line"><span>Node token (64 hex characters, from the panel Nodes page): 9f3a...c41d</span></span>
<span class="line"><span>Listen address [0.0.0.0]:</span></span>
<span class="line"><span>Listen port [8480]:</span></span></code></pre></div><p>The panel URL and token are validated (the token must be exactly 64 hex characters, with retry on bad input). It then:</p><ol><li>Installs the binaries to <code>/usr/local/bin</code> — built from source if Go is available, otherwise the prebuilt <code>bandwidth-noded</code> next to the script.</li><li>Writes <code>/etc/bandwidth-node/config.yaml</code> and <code>/etc/bandwidth-node/token</code> (both <code>0600</code>).</li><li>Installs and starts the <code>bandwidth-node.service</code> systemd unit.</li><li>Waits up to 90 seconds for the agent to register with the panel, and exits non-zero if registration is not confirmed.</li></ol><p>On start the agent calls <code>POST /api/bandwidth/node/register</code> on the panel (retrying with backoff until it succeeds). The panel records the node&#39;s reachable API URL and marks it online.</p><h3 id="_3-verify" tabindex="-1">3. Verify <a class="header-anchor" href="#_3-verify" aria-label="Permalink to &quot;3. Verify&quot;">​</a></h3><p>In the panel, <strong>Admin → Bandwidth → Nodes</strong> should show the node as <strong>online</strong> within a minute (the agent heartbeats every 60 seconds).</p><p>On the node itself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Public health endpoint (no auth required)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8480/api/v1/health</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;containers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;uptime_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;meta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Daemon + panel sync status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bandwidth-node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Live logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bandwidth-node.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">FIREWALL</p><p>The panel pulls stats and pushes limits over the node&#39;s API port. If you run <code>ufw</code> (or another firewall) on the node, allow it from the panel:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">panel-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8480</span></span></code></pre></div></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Node shows <strong>offline</strong> in the panel</td><td>Wrong panel URL or token during install</td><td>Check <code>journalctl -u bandwidth-node.service -f</code> for registration errors; re-run <code>install.sh</code> with the correct values</td></tr><tr><td>Node offline, logs show connection refused/timeouts</td><td>Panel unreachable from the node</td><td>Verify the panel URL resolves and is reachable: <code>curl -s https://panel.example.com/api/bandwidth/node/limits</code> should return <code>401</code>, not a network error</td></tr><tr><td>Panel can&#39;t pull stats from an online node</td><td>Firewall blocking port <code>8480</code></td><td><code>sudo ufw allow from &lt;panel-ip&gt; to any port 8480</code>; confirm with <code>curl http://&lt;node-ip&gt;:8480/api/v1/health</code> from the panel host</td></tr><tr><td>Installer exits with &quot;not confirmed panel registration&quot;</td><td>Registration didn&#39;t complete within 90 s</td><td><code>journalctl -u bandwidth-node.service -f</code> — common causes are a wrong panel URL, wrong token, or the panel being unreachable</td></tr><tr><td><strong>500 error</strong> on Admin → Bandwidth</td><td>Migrations not run, provider not registered, or stale opcache</td><td><code>php artisan migrate --force</code>; confirm <code>BandwidthMonitorServiceProvider</code> is in <code>config/app.php</code>; <code>php artisan config:clear &amp;&amp; php artisan route:clear</code>, then <code>sudo systemctl reload php8.2-fpm</code></td></tr><tr><td><strong>404</strong> on <code>/admin/bandwidth</code> after install</td><td>Stale route cache or opcache</td><td><code>php artisan route:clear</code> and reload php-fpm</td></tr><tr><td><code>tc not found</code> during node install</td><td>iproute2 missing</td><td>Install it (<code>apt install iproute2</code> / <code>dnf install iproute2</code>) and re-run</td></tr><tr><td>Node API returns <strong>401</strong> to the panel</td><td>Token was reset in the panel</td><td>Nothing to do — the agent detects the 401 and re-registers automatically with its configured token. If you rotated the token intentionally, update <code>/etc/bandwidth-node/token</code> and <code>sudo systemctl restart bandwidth-node</code></td></tr></tbody></table><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><h3 id="panel-addon" tabindex="-1">Panel addon <a class="header-anchor" href="#panel-addon" aria-label="Permalink to &quot;Panel addon&quot;">​</a></h3><p>Blueprint path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylbandwidth</span></span></code></pre></div><p>Standalone path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # keeps bandwidth_* table data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # also drops the bandwidth_* tables</span></span></code></pre></div><p>Both paths remove the provider from <code>config/app.php</code>, revert the sidebar and build-view patches, delete exactly the files the installer shipped, and clear the panel caches. By default your historical usage data, events and settings in the <code>bandwidth_*</code> tables are kept — pass <code>--purge-data</code> (standalone) only if you want them gone.</p><div class="warning custom-block"><p class="custom-block-title">ASSET PATH NOTE</p><p>The bundled Chart.js lives at <code>public/ext/bandwidth/chart.min.js</code> — deliberately <strong>outside</strong> <code>public/assets/</code>, which the panel&#39;s <code>yarn build:production</code> wipes on every frontend rebuild. If you ever see blank charts after a frontend rebuild, check that file still exists; everything else in the addon is build-proof.</p></div><h3 id="node-agent" tabindex="-1">Node agent <a class="header-anchor" href="#node-agent" aria-label="Permalink to &quot;Node agent&quot;">​</a></h3><p>On each Wings node, as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # full removal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keep-config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # keep /etc/bandwidth-node (config + token)</span></span></code></pre></div><p>This stops and disables the service, removes the <code>tc</code> rules the agent created from every container veth, and deletes the binaries, state (<code>/var/lib/bandwidth-node</code>), and logs (<code>/var/log/bandwidth-node</code>).</p><hr><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><p><strong>Panel:</strong> install the new <code>.blueprint</code> release over the old one (<code>blueprint -i &lt;new-version&gt;</code>), or re-run the standalone <code>install.sh</code>. The installer is idempotent, migrations are re-run safely, and existing node tokens and all historical data are preserved — no re-pairing required.</p><p><strong>Node agent:</strong> copy the new <code>node-module/</code> to the node and re-run <code>sudo bash install.sh</code>. The binaries are rebuilt/replaced and the service restarted. Byte counters, limits and the event queue live in SQLite at <code>/var/lib/bandwidth-node/bandwidth-node.db</code> and survive the upgrade; <code>tc</code> rules are re-applied on boot.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Open <strong>Admin → Bandwidth → Settings</strong> to set default speeds and day/week/month quotas — these prefill the bandwidth fields on every new server&#39;s build configuration.</li><li>Per-server overrides live under <strong>Admin → Bandwidth → Servers</strong>.</li><li>Questions or issues: <a href="https://xdp.network" target="_blank" rel="noreferrer">xdp.network</a>.</li></ul>`,69))])}const E=n(c,[["render",k]]);export{v as __pageData,E as default};
